use crate::ciphers::djb2::cipher::djb2_digest;
use crate::ciphers::djb2::keys::djb2_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one digest pass over `input_len` generated bytes.
pub fn djb2_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let seed = djb2_default_key();
    let watch = Stopwatch::start();
    let out = djb2_digest(&data, seed);
    std::hint::black_box(out);
    watch.elapsed_ns()
}
